picture_room.label:
[[[
      const fmt=(id)=>{
        if(!id) return '';
        const obj=states[id];
        if(!obj || ['unavailable','unknown'].includes(obj.state)) return 'Nicht verfügbar';
        const map={on:'Ein',off:'Aus',open:'Offen',closed:'Geschlossen',home:'Zuhause',not_home:'Abwesend',locked:'Verriegelt',unlocked:'Entriegelt',jammed:'Verklemmt'};
        if(obj.attributes.current_temperature!==undefined) return String(obj.attributes.current_temperature).replace('.',',')+' °C';
        const u=obj.attributes.unit_of_measurement||'';
        const n=Number(obj.state);
        return Number.isFinite(n)&&obj.state.trim()!=='' ? n.toLocaleString('de-DE',{maximumFractionDigits:1})+(u?' '+u:'') : (map[obj.state]||obj.state);
      };
      const lines=variables.rows||[];
      return lines.map(r=>`${r.icon||'•'} ${r.text||''}${r.entity?fmt(r.entity):''}`).join('<br>');
    ]]]

